import unittest
from inventory import parse_inventory

class Tests(unittest.TestCase):
    def test_normal(self):
        self.assertEqual(parse_inventory('apple,2\npear,0'), {'apple': 2, 'pear': 0})
    def test_escaped(self):
        self.assertEqual(parse_inventory(r'last\, first,3'), {'last, first': 3})
    def test_duplicate(self):
        with self.assertRaises(ValueError):
            parse_inventory('x,1\nx,2')
    def test_malformed(self):
        for value in ('missing', ',2', 'x,-1', 'x,nope'):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    parse_inventory(value)

